                ni,nj=i+di,j+dj
                if 0<=ni<h and 0<=nj<w and (ni,nj) in seen: continue
                if is_corr(ni,nj):
                    seen.add((ni,nj)); best[(ni,nj)]=dist+1; nf.append((ni,nj,dist+1))
                else:
